payload.template:
module counter #(parameter int N = 4) (
  input  logic         clk,
  input  logic         rst,
  input  logic         en,
  output logic [N-1:0] q
);

  // your code here: on each rising edge of clk,
  //   rst high  -> q becomes 0 (it wins over en)
  //   else en    -> q increases by one, wrapping at the top
  //   else       -> q holds
  // Clocked logic: non-blocking assignment.

endmodule

payload.testbench:
`timescale 1ns/1ps
// The sample testbench. Run uses this one; Submit uses a different
// one that tries cases this does not.
module tb;
  localparam int N = 4;
  logic clk = 1'b0;
  logic rst = 1'b1;
  logic en  = 1'b0;
  logic [N-1:0] q;

  counter #(.N(N)) dut (.clk(clk), .rst(rst), .en(en), .q(q));

  // 10 ns period
  always #5 clk = ~clk;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    // One edge with reset high, then read away from the edge.
    @(posedge clk); @(negedge clk);
    $display("CHECK reset 0 %0d AT %0d", q, $time);

    rst = 1'b0; en = 1'b1;
    repeat (3) @(posedge clk);
    @(negedge clk);
    $display("CHECK counted 3 %0d AT %0d", q, $time);

    en = 1'b0;
    repeat (2) @(posedge clk);
    @(negedge clk);
    $display("CHECK held 3 %0d AT %0d", q, $time);

    $display("DONE 3");
    $finish;
  end
endmodule
